document.addEventListener("DOMContentLoaded",(function(){document.querySelectorAll(".password-toggle").forEach(btn=>{btn.addEventListener("click",()=>{const input=btn.previousElementSibling,icon=btn.querySelector(".icon-eye"),isHidden="password"===input.type;input.type=isHidden?"text":"password",icon.dataset.icon=isHidden?"crossed":"open",btn.setAttribute("aria-label",isHidden?"Hide pin":"Show pin")})})}));